/**
 * Plain-language explanations for every template-analyzer issue code
 * (`template_analyze.py`; the list is `templateIssueCodes.json`, regenerated by
 * `scripts/export_issue_codes.py`). A vitest fails when a code has no entry here.
 */
export type IssueHelp = {
  title: string;
  why: string;
  /** Steps in Microsoft Word. */
  word?: string;
  /** Steps in Google Docs. */
  docs?: string;
  /** A fix inside this app (the mapping step, a re-upload). */
  app?: string;
  /** Offer "use a default template instead" (layout the app cannot edit). */
  useDefault?: boolean;
};

const TABLE_WORD =
  "Copy the resume text into a new blank document so it is ordinary single-column paragraphs, re-apply your fonts and headings, then save as .docx.";
const TABLE_DOCS =
  "Select everything in the table, copy it, paste it below the table with Edit → Paste without formatting, then delete the table (right-click → Delete table) and restyle the headings.";
const REMAP = "Fix the field mapping in the next step, or re-upload the file to start over.";
const LIST_WORD = "Select the lines and click Home → Bullets so each is a real Word list item.";
const LIST_DOCS = "Select the lines and click Format → Bullets & numbering → Bulleted list.";

const layout = (title: string, why: string): IssueHelp => ({
  title,
  why,
  word: TABLE_WORD,
  docs: TABLE_DOCS,
  useDefault: true,
});

const mapping = (title: string, why: string): IssueHelp => ({ title, why, app: REMAP });

