/** Explanation for `code`, or a generic one for a code this build doesn't know. */
export function issueHelp(code: string): IssueHelp {
  return (
    TEMPLATE_ISSUES[code] ?? {
      title: "Template issue",
      why: "The analyzer flagged something in this document; see the details.",
    }
  );
}
